#!/usr/bin/env python3
"""Independent replication of the AROC adjacent-pair similarity statistics.

Measures (defined explicitly):
  prefix_ratio(a,b) = len(longest common prefix) / max(len(a),len(b))
  suffix_ratio(a,b) = same on reversed strings
  char_overlap(a,b) = Jaccard similarity of character sets
  length_diff(a,b)  = abs(len(a)-len(b))

Adjacent = consecutive tokens within a manuscript line.
Shuffled = random token pairs from the corpus (null model), fixed seed.
"""
import random
from decipher import load_corpus, flatten


def lcp(a, b):
    n = 0
    for x, y in zip(a, b):
        if x != y:
            break
        n += 1
    return n


def prefix_ratio(a, b):
    return lcp(a, b) / max(len(a), len(b), 1)


def suffix_ratio(a, b):
    return lcp(a[::-1], b[::-1]) / max(len(a), len(b), 1)


def char_overlap(a, b):
    sa, sb = set(a), set(b)
    return len(sa & sb) / max(len(sa | sb), 1)


def length_diff(a, b):
    return abs(len(a) - len(b))


def mean(vals):
    return sum(vals) / len(vals) if vals else 0.0


def main():
    corpus = load_corpus("voynich_words.txt")
    adj = [(l[i], l[i + 1]) for l in corpus for i in range(len(l) - 1)]
    toks = flatten(corpus)
    rng = random.Random(42)
    shuf = [(rng.choice(toks), rng.choice(toks)) for _ in range(len(adj))]

    for name, fn in [("shared-prefix ratio", prefix_ratio),
                     ("shared-suffix ratio", suffix_ratio),
                     ("character-set overlap", char_overlap),
                     ("length difference", length_diff)]:
        a, s = mean([fn(x, y) for x, y in adj]), mean([fn(x, y) for x, y in shuf])
        if name == "length difference":
            print("%-22s adjacent %.4f  shuffled %.4f  (%s)" %
                  (name, a, s, "closer locally" if a < s else "NOT closer"))
        else:
            print("%-22s adjacent %.4f  shuffled %.4f  (%+.1f%%)" %
                  (name, a, s, 100 * (a - s) / s if s else 0))
    print("n adjacent pairs: %d" % len(adj))


if __name__ == "__main__":
    main()

