    );

    /// @notice Anchor one YETI root. Reverts on zero root, duplicate root,
    ///         or inconsistent counts. Every frame yields exactly one trail
    ///         record, so admitted + refused must equal frames.
    function anchor(
        bytes32 root,
        uint64 frames,
        uint64 admitted,
        uint64 refused,
        string calldata meta
    ) external {
        require(root != bytes32(0), "zero root");
        require(attestations[root].anchoredAt == 0, "already anchored");
        require(admitted + refused == frames, "counts inconsistent");
        attestations[root] = Attestation({
            root: root,
            frames: frames,
            admitted: admitted,
            refused: refused,
            anchoredAt: uint64(block.timestamp),
            anchorer: msg.sender,
            meta: meta
        });
        roots.push(root);
        emit Anchored(root, msg.sender, frames, admitted, refused);
    }

    /// @notice Number of anchored roots.
    function count() external view returns (uint256) {
        return roots.length;
    }
}

